package main

import (
	"fmt"
	"math/rand"
)

func main() {
	fmt.Println("=== If Else Standar ===")
	status := "running"
	if status == "running" {
		fmt.Println("Sistem beroperasi normal.")
	} else {
		fmt.Println("Sistem down!")
	}

	fmt.Println("\n=== If dengan Inisialisasi Pendek ===")
	// Mendeklarasikan 'cpuUsage' khusus untuk blok if-else ini saja.
	// Sangat sering digunakan dalam error handling di Go.
	if cpuUsage := rand.Intn(100); cpuUsage > 80 {
		fmt.Printf("ALERT: Penggunaan CPU sangat tinggi! (%d%%)\n", cpuUsage)
	} else if cpuUsage > 50 {
		fmt.Printf("WARNING: Penggunaan CPU meningkat. (%d%%)\n", cpuUsage)
	} else {
		fmt.Printf("OK: Penggunaan CPU aman. (%d%%)\n", cpuUsage)
	}

	// cpuUsage tidak bisa diakses di sini.
	// fmt.Println(cpuUsage) // Akan error undefined jika diaktifkan
}
